#include <iostream>
#include <cstdio>
#include <cstring>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

using llong = long long;
const int MAX_N = 66;

int R, C, N, i;
char S[MAX_N];
llong CMB[MAX_N][MAX_N];

int cntA[MAX_N], cntB[MAX_N];
vector<llong> PART[MAX_N], ZERO_PART[MAX_N];

void build_comb() {
    for (int i = 0; i <= N; ++i) {
        CMB[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            CMB[i][j] = CMB[i-1][j-1] + CMB[i-1][j];
    }
}

llong calc_diff(int cfg, int a_cnt, int b_cnt) {
    llong res = 0;
    llong t1, t2;

    for (int k = 0; k < C + 1; ++k) {
        if (cfg & (1 << k)) {
            ++b_cnt;
            t1 = CMB[b_cnt - 1][R - 1];
            t2 = CMB[N - b_cnt][R] - CMB[a_cnt][R];
            res -= t1 * t2;
        } else {
            ++a_cnt;
            t1 = CMB[a_cnt - 1][R - 1];
            t2 = CMB[N - a_cnt][R] - CMB[b_cnt][R];
            res += t1 * t2;
        }
    }
    return res;
}

bool check_cfg(int cfg) {
    for (int k = 0; k < C + 1; ++k) {
        if (S[2 * R + C + k] == 'A' && ((cfg >> k) & 1) == 1) return false;
        if (S[2 * R + C + k] == 'B' && ((cfg >> k) & 1) == 0) return false;
    }
    return true;
}

void build_parts() {
    int max_cfg = 1 << (C + 1);

    for (int cfg = 0; cfg < max_cfg; ++cfg) {
        int b_cnt = __builtin_popcount(cfg);
        int a_cnt = C + 1 - b_cnt;

        if (check_cfg(cfg))
            PART[a_cnt].push_back(calc_diff(cfg, R + C - a_cnt, R + C - b_cnt));
        else
            ZERO_PART[a_cnt].push_back(calc_diff(cfg, R + C - a_cnt, R + C - b_cnt));
    }

    for (int k = 0; k <= C + 1; ++k) {
        sort(PART[k].begin(), PART[k].end());
        sort(ZERO_PART[k].begin(), ZERO_PART[k].end());
    }
}

llong get_mult(int cfg) {
    int i, j;

    for (i = 0; i < C + 1; ++i)
        if (((cfg >> i) & 1) != (cfg & 1))
            break;

    for (j = i; j < C + 1; ++j) {
        if (S[2 * R - 1 + j] == 'A' && (((cfg >> j) & 1) == 1)) return 0;
        if (S[2 * R - 1 + j] == 'B' && (((cfg >> j) & 1) == 0)) return 0;
    }

    int set_a = R - 1 + ((cfg & 1) == 0 ? i : 0);
    int set_b = R - 1 + ((cfg & 1) == 1 ? i : 0);

    if (set_a < cntA[2 * R - 2 + i]) return 0;
    if (set_b < cntB[2 * R - 2 + i]) return 0;
    return CMB[set_a + set_b - cntA[2 * R - 2 + i] - cntB[2 * R - 2 + i]][set_a - cntA[2 * R - 2 + i]];
}

void update(pair<llong, llong>& best, pair<llong, llong> cand) {
    if (cand.first < 0) cand.first = -cand.first;

    if (best.first < cand.first) return;
    if (best.first > cand.first) {
        best = cand;
        return;
    }
    best.second += cand.second;
}

llong count_val(const vector<llong>& v, llong val) {
    auto lo = lower_bound(v.begin(), v.end(), val);
    auto hi = upper_bound(v.begin(), v.end(), val);
    return hi - lo;
}

llong solve_part() {
    int max_cfg = 1 << (C + 1);
    pair<llong, llong> best = make_pair(1LL << 60, 0);

    for (int cfg = 0; cfg < max_cfg; ++cfg) {
        int b_cnt = __builtin_popcount(cfg);
        int a_cnt = C + 1 - b_cnt;
        llong cur = calc_diff(cfg, R - 1, R - 1);

        llong mult = get_mult(cfg);
        auto it = lower_bound(PART[C + 1 - a_cnt].begin(), PART[C + 1 - a_cnt].end(), -cur);

        if (it != PART[C + 1 - a_cnt].end()) {
            if (best.first >= abs(*it + cur)) {
                llong mult2 = count_val(PART[C + 1 - a_cnt], *it);
                update(best, make_pair(*it + cur, mult * mult2));
            }
        }

        if (it != PART[C + 1 - a_cnt].begin()) {
            --it;
            if (best.first >= abs(*it + cur)) {
                llong mult2 = count_val(PART[C + 1 - a_cnt], *it);
                update(best, make_pair(*it + cur, mult * mult2));
            }
        }

        mult = 0;
        it = lower_bound(ZERO_PART[C + 1 - a_cnt].begin(), ZERO_PART[C + 1 - a_cnt].end(), -cur);

        if (it != ZERO_PART[C + 1 - a_cnt].end()) {
            llong mult2 = count_val(ZERO_PART[C + 1 - a_cnt], *it);
            if (best.first >= abs(*it + cur)) {
                update(best, make_pair(*it + cur, mult * mult2));
            }
        }

        if (it != ZERO_PART[C + 1 - a_cnt].begin()) {
            --it;
            if (best.first >= abs(*it + cur)) {
                llong mult2 = count_val(ZERO_PART[C + 1 - a_cnt], *it);
                update(best, make_pair(*it + cur, mult * mult2));
            }
        }
    }

    return best.second;
}

int main() {
    scanf("%d%d\n%s", &R, &C, S + 1);
    N = 2 * (R + C);

    build_comb();

    for (i = 1; i <= N; ++i) {
        cntA[i] = cntA[i - 1] + (S[i] == 'A' ? 1 : 0);
        cntB[i] = cntB[i - 1] + (S[i] == 'B' ? 1 : 0);
    }

    build_parts();
    llong ans = solve_part();
    printf("%lld", ans);

    return 0;
}
